import { Buffer } from "node:buffer";
export default async function attachmentContent(
  {
    remote,
    inline,
    transitUrl,
    size,
    expectedMessageId,
    expectedAttachmentId,
    downloadedMessageId,
    downloadedAttachmentId,
    downloadedSize,
  },
  context,
) {
  let bytes;
  if (remote) {
    if (
      downloadedMessageId !== expectedMessageId ||
      downloadedAttachmentId !== expectedAttachmentId ||
      downloadedSize !== size
    )
      throw Error("Unexpected Gmail attachment result");
    if (typeof transitUrl !== "string" || !/^https:\/\//.test(transitUrl))
      throw Error("Invalid attachment transit URL");
    const response = await context.fetch(transitUrl, { method: "GET" });
    if (!response.ok) throw Error("Attachment download failed");
    bytes = Buffer.from(await response.arrayBuffer());
  } else {
    if (typeof inline !== "string" || !/^[A-Za-z0-9_-]*={0,2}$/.test(inline))
      throw Error("Invalid inline attachment");
    const normalized = inline.replace(/-/g, "+").replace(/_/g, "/").replace(/=+$/, "");
    bytes = Buffer.from(normalized, "base64");
    if (bytes.toString("base64").replace(/=+$/, "") !== normalized)
      throw Error("Invalid inline attachment encoding");
  }
  if (bytes.length !== size) throw Error("Attachment size mismatch");
  return { contentBase64: bytes.length ? bytes.toString("base64") : null };
}

