export default function prompt({ pdfText, xml, status, errors }) {
  if (
    !pdfText?.trim() ||
    pdfText.length > 30000 ||
    xml.length > 30000 ||
    errors?.length ||
    (status && status !== "Completed")
  )
    throw Error("Invoice extraction failed or exceeds bounds");
  return {
    prompt:
      "Extrae de la factura colombiana PDF y XML. Devuelve solamente JSON con Tipo (Factura o Nota Crédito), Numero_Factura, Fecha_Emision YYYY-MM-DD, CUFE, NIT_Emisor, Razon_Social_Emisor, NIT_Receptor, Valor_Antes_Impuesto, Impuesto, Total y Resumen_Compra. NIT sin dígito de verificación; importes números; resumen máximo 20 palabras. No inventes datos. PDF:\n" +
      pdfText +
      "\nXML:\n" +
      xml,
  };
}

