    "Fecha_Emision",
    "CUFE",
    "NIT_Emisor",
    "Razon_Social_Emisor",
    "NIT_Receptor",
    "Resumen_Compra",
  ];
  if (
    required.some((k) => typeof x[k] !== "string" || !x[k].trim()) ||
    !["Factura", "Nota Crédito"].includes(x.Tipo) ||
    !/^\d{4}-\d{2}-\d{2}$/.test(x.Fecha_Emision) ||
    !/^\d+$/.test(x.NIT_Emisor) ||
    !/^\d+$/.test(x.NIT_Receptor) ||
    !/^[-A-Za-z0-9_]+$/.test(x.Numero_Factura) ||
    ["Valor_Antes_Impuesto", "Impuesto", "Total"].some(
      (k) => typeof x[k] !== "number" || !Number.isFinite(x[k]),
    ) ||
    Math.abs(x.Valor_Antes_Impuesto + x.Impuesto - x.Total) > 0.01
  )
    throw Error("Invoice values missing or totals do not balance");
  const key = "col-invoice:" + messageId + ":" + fileState.index,
    state = await ctx.state.get(key);
  let prior = state;
  if (prior?.phase?.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending invoice write " + key);
    if (prior.phase === "pending-drive" && resolution === "confirmed") {
      if (!driveId) throw Error("Provide confirmed Drive file ID");
      prior = { ...prior, phase: "sheet", driveId };
      await ctx.state.set(key, prior);
    } else if (prior.phase === "pending-sheet" && resolution === "confirmed") {
      await ctx.state.set(key, { phase: "done" });
      return { key, step: "done", name: "unused.pdf", rows: [[]], headers: [], invoice: {} };
    } else if (prior.phase === "pending-drive") {
      prior = null;
      await ctx.state.set(key, null);
    } else {
      prior = { ...prior, phase: "sheet" };
      await ctx.state.set(key, prior);
    }
  }
  if (prior?.phase === "done")
    return { key, step: "done", name: "unused.pdf", rows: [[]], headers: [], invoice: {} };
  if (prior && !["sheet"].includes(prior.phase)) throw Error("Invalid invoice state");
  if (prior?.invoice) x = prior.invoice;
  const headers = [
      "Key",
      "Tipo",
      "Factura",
      "Fecha",
      "NIT Emisor",
      "NIT Receptor",
      "Razón Social",
      "Subtotal",
      "Impuesto",
      "Total",
      "CUFE",
      "Resumen Compra",
    ],
    row = [
      x.NIT_Emisor + "-" + x.Numero_Factura,
      x.Tipo,
      x.Numero_Factura,
      x.Fecha_Emision,
      x.NIT_Emisor,
      x.NIT_Receptor,
      x.Razon_Social_Emisor,
      x.Valor_Antes_Impuesto,
      x.Impuesto,
      x.Total,
      x.CUFE,
      x.Resumen_Compra,
    ];
  return {
    key,
    step: prior ? "sheet" : "drive",
    name: x.Fecha_Emision + "-" + x.Numero_Factura + ".pdf",
    rows: [row],
    headers,
    invoice: x,
  };
}

