  const old = await ctx.state.get(key);
  if (phase === "drive" && old) throw Error("Unexpected invoice state");
  if (phase === "sheet" && old?.phase !== "sheet") throw Error("Unexpected sheet state");
  await ctx.state.set(
    key,
    phase === "drive" ? { phase: "pending-drive", invoice } : { ...old, phase: "pending-sheet" },
  );
  return { ok: true };
}

